        console.print(f"  Turn timeout: {mt_config.get('turn_timeout_s', 90)}s")
        console.print(f"  Confidence threshold: {mt_config.get('confidence_threshold', 0.8)}")
        console.print(f"  Temperature schedule: {mt_config.get('temperature_schedule', 'fixed')}")
        console.print(f"  Planning turn: {mt_config.get('planning_turn', True)}")
        console.print(f"  Verification turn: {mt_config.get('verification_turn', True)}")
        console.print(f"  Retry on low confidence: {mt_config.get('retry_on_low_confidence', True)}")
        console.print(f"  Context reserve: {mt_config.get('context_reserve_pct', 20)}%")
        mt_phases = mt_config.get("phases", [])
