                    if t.get("retries", 0) > 0:
                        console.print(f"  [dim]retries: {t['retries']}[/dim]")
                elif turn_type == "synthesis":
                    console.print(
                        "\n[bold magenta]Synthesis turn:[/bold magenta]"
                    )

            if result.get("escalated"):
                console.print(
                    f"\n[red]Escalated: {result.get('reason', '?')}[/red]"
                )
            else:
                console.print("\n[green]Completed locally[/green]")

