def load_config() -> dict:
    import os

    project_dir = os.environ.get("DATUM_PROJECT_DIR", ".")
    for config_path in [
        Path(project_dir) / ".datum/config.toml",
        Path(".datum/config.toml"),
        Path("assets/config.toml.default"),
    ]:
        if not config_path.exists():
            continue
        try:
            import tomllib
        except ImportError:
            try:
                import tomli as tomllib
            except ImportError:
                return DEFAULTS.copy()
        with config_path.open("rb") as f:
            config = tomllib.load(f)
        local = config.get("local_llm", {})
        return {**DEFAULTS, **local}

    return DEFAULTS.copy()


def should_use_local(phase: str) -> bool:
    if not is_available():
        return False
    config = load_config()
    if not config.get("enabled", False):
        return False
    return phase in config.get("phases", [])


def main() -> None:
    if len(sys.argv) < 2:
        config = load_config()
        print(json.dumps({"available": is_available(), "config": config}, indent=2))
        return

    prompt = " ".join(sys.argv[1:])
    if not is_available():
        print(json.dumps({"error": "MLX not available"}))
        sys.exit(1)

    config = load_config()
    print(f"Loading {config['model']}...", file=sys.stderr)
    result = generate(
        prompt,
        model_id=config["model"],
        max_tokens=config.get("max_tokens", DEFAULTS["max_tokens"]),
        temperature=config.get("temperature", DEFAULTS["temperature"]),
    )
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

def _execute_tool(tool_call: dict, mt_config: dict) -> str:
    import subprocess
    import json

    tool_name = tool_call.get("tool_name", "")
    tool_args = tool_call.get("tool_args", {})

    allowed = mt_config.get("allowed_tools", [])
    if allowed and tool_name not in allowed:
        return f"Error: Tool '{tool_name}' is not in allowed_tools list."

    cmd = [sys.executable, "scripts/lane-tools-runner.py", tool_name]

    if isinstance(tool_args, dict):
        # Layer 1 Defense: Route system commands through rtk natively
        if tool_name == "run_command" and "command" in tool_args:
            orig_cmd = tool_args["command"]
            if not orig_cmd.startswith("rtk "):
                tool_args["command"] = f"rtk proxy {orig_cmd}"
        cmd.append(json.dumps(tool_args))
    elif isinstance(tool_args, list):
        cmd.extend(str(a) for a in tool_args)
    else:
        cmd.append(str(tool_args))

    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
        out = proc.stdout
        if proc.stderr:
            out += "\nSTDERR:\n" + proc.stderr
        if not out.strip():
            out = f"Tool exited with code {proc.returncode} (no output)"

        # Layer 3 Defense: Head+Tail Truncation
        return _truncate_tool_output(out)
    except subprocess.TimeoutExpired:
        return "Error: Tool execution timed out."
    except Exception as e:
        return f"Error executing tool: {e}"

