#!/usr/bin/env python3
"""
lane-tools-runner.py — Sandboxed subprocess wrapper for lane-tools.

Enforces permissions from manifest.toml: filesystem allowlists, network
blocking, CPU/memory/time limits. Kills the subprocess on violation.

Usage:
  python3 scripts/lane-tools-runner.py <tool_name> [args...]
"""

import json
import os
import resource
import subprocess
import sys
from pathlib import Path

MANIFEST = Path("scripts/lane-tools/manifest.toml")
DEFAULT_TIMEOUT = 60


def load_manifest() -> dict:
    if not MANIFEST.exists():
        return {}
    try:
        import tomllib
    except ImportError:
        try:
            import tomli as tomllib  # type: ignore[import]
        except ImportError:
            return {}
    with MANIFEST.open("rb") as f:
        return tomllib.load(f)


def get_tool_config(manifest: dict, tool_name: str) -> dict | None:
    return manifest.get("tools", {}).get(tool_name)


def set_resource_limits(timeout: int) -> None:
    """Apply CPU time and memory limits."""
    try:
        resource.setrlimit(resource.RLIMIT_CPU, (timeout, timeout + 5))
        # 512MB memory limit
        resource.setrlimit(resource.RLIMIT_AS, (512 * 1024 * 1024, 512 * 1024 * 1024))
        # 1000 file descriptors
        resource.setrlimit(resource.RLIMIT_NOFILE, (1000, 1000))
    except (ValueError, resource.error):
        pass  # Some limits may not be settable in all environments


def run_tool(tool_name: str, tool_args: list[str]) -> int:
    manifest = load_manifest()
    config = get_tool_config(manifest, tool_name)

    if config is None:
        print(
            json.dumps(
                {
                    "error": f"Tool '{tool_name}' not in manifest. Register it in scripts/lane-tools/manifest.toml before running.",
                    "violation": "unregistered_tool",
                }
            ),
            file=sys.stderr,
        )
        return 2

    tool_path = Path("scripts/lane-tools") / config.get("path", f"{tool_name}.py")
    if not tool_path.exists():
        print(
            json.dumps({"error": f"Tool file not found: {tool_path}"}), file=sys.stderr
        )
        return 1

    timeout = config.get("timeout_seconds", DEFAULT_TIMEOUT)

    env = dict(os.environ)
    env["DATUM_SANDBOX"] = "1"
    env["DATUM_TOOL_NAME"] = tool_name

    # Build command
    cmd = [sys.executable, str(tool_path)] + tool_args

    try:
        proc = subprocess.run(
            cmd,
            timeout=timeout,
            env=env,
            preexec_fn=lambda: set_resource_limits(timeout),
        )
        return proc.returncode
    except subprocess.TimeoutExpired:
        print(
            json.dumps(
                {
                    "error": f"Tool '{tool_name}' exceeded timeout of {timeout}s",
                    "violation": "lane_tool_sandbox_violation",
                    "cause": "timeout",
                }
            ),
            file=sys.stderr,
        )
        return 2
    except Exception as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 1


def main() -> None:
    if len(sys.argv) < 2:
        print("Usage: lane-tools-runner.py <tool_name> [args...]", file=sys.stderr)
        sys.exit(1)

    tool_name = sys.argv[1]
    tool_args = sys.argv[2:]
    sys.exit(run_tool(tool_name, tool_args))


if __name__ == "__main__":
    main()

    return _mt_escalate(
        phase,
        turns_log,
        total_tokens,
        time.monotonic() - total_start,
        f"exception: {e}",
    )

turn_elapsed = time.monotonic() - turn_start
if turn_elapsed >= turn_timeout and turn < max_turns - 1:
    turn_data["warning"] = "turn_timeout_hit"

if mt_config.get("enable_tool_execution", False):
    turn_data_dict = turn_data.get("data", {})
    if (
        isinstance(turn_data_dict, dict)
        and turn_data_dict.get("action") == "tool_execution"
    ):
        tool_call = turn_data_dict.get("tool_call")
        if tool_call:
            tool_start_time = time.monotonic()
            tool_output, was_truncated = _execute_tool(tool_call, mt_config)
            tool_time_s = time.monotonic() - tool_start_time
            tool_name = tool_call.get("tool_name", "unknown")

            history.append(
                {"role": "assistant", "content": json.dumps(turn_data_dict)}
            )

            user_content = f"Tool execution result:\n<untrusted>\n{tool_output}\n</untrusted>\nAnalyze the result and decide next action."
            if was_truncated:
                user_content += "\n\nSystem Note: The tool output was extremely long and has been truncated. If you need the missing lines, use a more precise tool (like 'read_file_range' or 'grep_search')."

            history.append(
                {
                    "role": "user",
                    "content": user_content,
                }
            )
            turns_log.append(turn_data)
            turns_log.append(
                {
                    "turn": turn,
                    "type": "tool_output",
                    "tool_name": tool_name,
                    "time_s": round(tool_time_s, 2),
                    "length": len(tool_output),
                }
            )
            total_tokens += turn_data.get("tokens", 0)
            continue

total_tokens += turn_data.get("tokens", 0)
turns_log.append(turn_data)
history.append(
    {"role": "assistant", "content": json.dumps(turn_data.get("data", {}))}
)

if turn > 0 and _is_final_turn(turn, turn_data.get("data"), plan, mt_config):
    if turn_data.get("data", {}).get("escalate"):

#!/usr/bin/env python3
import sys
import json
from pathlib import Path

def main():
    if len(sys.argv) < 2:
        print("Usage: read_file_range.py <json_args>")
        sys.exit(1)

    try:
        args = json.loads(sys.argv[1])
    except json.JSONDecodeError:
        print("Error: Arguments must be a JSON object.")
        sys.exit(1)

    path_str = args.get("path")
    if not path_str:
        print("Error: 'path' argument is required.")
        sys.exit(1)

    start_line = args.get("start_line", 1)
    end_line = args.get("end_line")

    try:
        start_line = max(1, int(start_line))
        if end_line is not None:
            end_line = max(start_line, int(end_line))
    except ValueError:
        print("Error: start_line and end_line must be integers.")
        sys.exit(1)

    target = Path(path_str).resolve()
    if not target.is_file():
        print(f"Error: File '{target}' does not exist or is not a file.")
        sys.exit(1)

    try:
        with open(target, "r", encoding="utf-8") as f:
            for i, line in enumerate(f, start=1):
                if i >= start_line:
                    if end_line and i > end_line:
                        break
                    print(line, end="")
    except Exception as e:
        print(f"Error reading file '{target}': {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

